-- Clinic locations (no marketing): clinics that never receive newsletters. Holds non-marketing clinic contacts
-- and lab network sites such as Quest and LabCorp patient service centers, which may have no email.
do $$ declare c text; begin
  for c in select conname from pg_constraint where conrelid = 'contact_imports'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%list%'
  loop execute format('alter table contact_imports drop constraint %I', c); end loop;
end $$;
alter table contact_imports add constraint contact_imports_list_check check (list in ('employers', 'clinics', 'treatment', 'corrections', 'clinic-locations'));
alter table contact_imports alter column email drop not null;
alter table contact_imports add constraint contact_imports_email_or_place check (email is not null or (company is not null and address is not null));
create unique index if not exists contact_imports_place on contact_imports (lower(company), lower(address), coalesce(zip, '')) where email is null;

-- HubSpot clinic contacts that are not marketing contacts. Existing contacts keep their list.
create temp table hs_places (email text, first_name text, last_name text, company text, address text, address2 text, city text, state text, zip text, phone text) on commit drop;

do $$
declare total int; existing int; added int;
begin
  select count(*) into total from hs_places;
  select count(*) into existing from contact_imports c where lower(c.email) in (select lower(email) from hs_places);
  select distinct on (lower(h.email)) lower(h.email), h.first_name, h.last_name, h.company, h.address, h.address2, h.city, h.state, h.zip, h.phone,
    'hubspot', 'HubSpot non-marketing clinic contacts (2026-11-22)', 'clinic-locations', 'assigned', now()
  from hs_places h where not exists (select 1 from contact_imports c where lower(c.email) = lower(h.email))
  order by lower(h.email);
  get diagnostics added = row_count;
  raise notice '[clinic-locations import] % in file; % added to Clinic locations; % already on file, left as is', total, added, existing;
end $$;
